const inbound = $input.first().json;
const body = inbound.body ?? inbound.data ?? inbound;
const rawDiagnoses = body.diagnoses ?? body.diagnosis ?? body.diagnosisList ?? [];
const diagnosisArray = Array.isArray(rawDiagnoses)
  ? rawDiagnoses
  : String(rawDiagnoses).split(/[,;|]/).map((s) => s.trim()).filter(Boolean);
const normalized = diagnosisArray.map((d) => d.toLowerCase());
const has = (...needles) => needles.some((needle) => normalized.some((d) => d.includes(needle)));
const requestedForm = String(body.formType ?? body.packetType ?? body.requestedForm ?? body.form ?? '').trim().toLowerCase();
const demographics = {
  dateOfBirth: body.dateOfBirth ?? body.dob ?? body.birthDate ?? '',
  sexAtBirth: body.sexAtBirth ?? body.sex ?? '',
  genderIdentity: body.genderIdentity ?? body.gender ?? '',
  race: body.race ?? '',
  ethnicity: body.ethnicity ?? '',
  preferredLanguage: body.preferredLanguage ?? body.language ?? '',
  phone: body.phone ?? body.telephone ?? body.mobile ?? '',
};
return [{ json: { patientId: body.patientId ?? body.id ?? '', patientName: body.patientName ?? body.name ?? '', patientEmail: body.patientEmail ?? body.email ?? body.contactEmail ?? '', requestedForm, demographics, diagnoses: diagnosisArray, diagnosisFlags: { depression: has('depression', 'mdd', 'major depressive', 'dysthymia'), anxiety: has('anxiety', 'gad', 'generalized anxiety'), adhd: has('adhd', 'attention deficit'), adl: has('adl', 'iadl', 'activities of daily living', 'functional impairment', 'functionality'), bipolar: has('bipolar', 'mania', 'hypomania') } } }];

const ctx = $('Normalize Diagnosis Packet').first().json;
const formResponse = $json;
const now = new Date().toISOString();
const safeName = (ctx.patientName || ctx.patientId || 'patient').toString().replace(/[^a-z0-9_-]+/gi, '_').replace(/^_+|_+$/g, '');
const packet = {
  packetType: 'PHQ-9',
  formNode: 'Depression Screening Email',
  patientId: ctx.patientId,
  patientName: ctx.patientName,
  patientEmail: ctx.patientEmail,
  demographics: ctx.demographics,
  requestedForm: ctx.requestedForm,
  diagnoses: ctx.diagnoses,
  diagnosisFlags: ctx.diagnosisFlags,
  documentPath: '/psychiatry/evaluation_forms/phq9',
  documentType: 'PHQ-9',
  documentSlug: 'phq9',
  documentFilename: `${now.slice(0, 10)}-phq9-${safeName}.json`,
  capturedAt: now,
  formResponse,
};
const content = JSON.stringify(packet, null, 2);
return [{
  json: {
    ...packet,
    baseUrl: $env.OPENEMR_BASE_URL,
    siteId: $env.OPENEMR_SITE_ID || 'default',
    token: $env.OPENEMR_ACCESS_TOKEN || '',
  },
  binary: {
    data: {
      data: Buffer.from(content, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: packet.documentFilename,
    },
  },
}];

